def orfs(s, minaa=80):
    res=[]
    for f in range(3):
        p = translate(s[f:])
        start=0
        for j,ch in enumerate(p):
            if ch=='*':
                if j-start>=minaa: res.append((f,start,j))
                start=j+1
        if len(p)-start>=minaa: res.append((f,start,len(p)))
