seq = ""
for l in open('region.fasta'):
    if not l.startswith('>'): seq += l.strip()
comp = {'A':'T','T':'A','G':'C','C':'G','N':'N'}
rc = ''.join(comp[c] for c in reversed(seq))
bases='TCAG'
aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
codon={}
i=0
for a in bases:
    for b in bases:
        for c in bases:
            codon[a+b+c]=aas[i]; i+=1

def aa_of(s,p):
    return codon.get(s[p:p+3],'X')

def ext(s,p):   # number of sense codons from p (codon starts at p, p+3,...) until stop
    n=0
    while p+3<=len(s):
        a=aa_of(s,p)
        if a=='*': break
        n+=1; p+=3
    return n

def upext(s,p): # number of sense codons immediately before position p, in frame where codons end at p
    n=0
    while p>=3:
        a=aa_of(s,p-3)
        if a=='*': break
        n+=1; p-=3
    return n

best=[]
for tag,s in [('fwd',seq),('rev',rc)]:
    for p in range(3,len(s)-3):
        for f in range(3):
            if p%3 != f%3: continue
            # upstream frame f: codons ending at p
            up = upext(s,p)
            for d in (1,-1):
                g=(f+d)%3
                # downstream starts at q with q%3==g%3 and q near p
                for dq in (0,1,2):
                    q=p+dq
                    if q%3!=g%3: continue
                    dn=ext(s,q)
                    if up+dn>150:
                        best.append((up+dn,tag,p,f,d,g,q,up,dn))
best.sort(reverse=True)
for b in best[:15]:
    print(b)
