def revcomp(s): return ''.join(comp[c] for c in reversed(s))

def find_irs(s, start, end, minstem=4, maxloop=60):
    res=[]
    sub = s[start:end]
    n=len(sub)
    for i in range(n):
        for j in range(i+minstem+3, n):
            for L in range(minstem, 12):
                if i+L>n or j+L>n: continue
                a=sub[i:i+L]; b=sub[j:j+L]
                if a==revcomp(b):
                    loop=j-(i+L)
                    if 0<=loop<=maxloop:
                        res.append((i+start, j+start, L, loop, a, sub[i:j+L]))
    return res

